import { css, html, nothing, svg, type TemplateResult } from 'lit';
import { rnd, type Ctx, type Scene, type Visitor } from './types';

/**
 * A Western Australian beach behind the Glass look's "sea" and "sunset" themes.
 * The glass panels hide the middle of the picture, so the world is composed for what stays open:
 * the sky band along the top (clouds, sun or moon, everything that flies) and the dune corners at the bottom
 * (grass, the patrol flag, everything that walks). The water moves as large soft bands, which is all the glass lets through.
 * Drawings are built from two or three tones a surface with no outlines; creatures are split into parts that move on their own pivots.
 */

const lerp = (pts: number[][], m: number): number => { if (m <= pts[0][0]) return pts[0][1]; for (let i = 1; i < pts.length; i++) if (m <= pts[i][0]) { const [a, b] = [pts[i - 1], pts[i]]; return a[1] + ((b[1] - a[1]) * (m - a[0])) / (b[0] - a[0]); } return pts[pts.length - 1][1]; };
/** the sand corners beside the bottom bar are clear only on a wide screen: on a phone nothing that walks would be seen */
const wide = (): boolean => typeof innerWidth !== 'number' || innerWidth >= 1000;
const light = (c: Ctx): boolean => c.tod !== 'night';
const golden = (c: Ctx): boolean => c.tod === 'eve' || (c.theme === 'sunset' && c.tod !== 'night');
const stars = (n: number, seed: number): string => { const r = rnd(seed); return Array.from({ length: n }, () => `${(4 + r() * 92).toFixed(1)}vw ${(6 + r() * 96).toFixed(0)}px 0 ${r() < 0.3 ? 1 : 0}px #fff`).join(','); };

// ---- drawings shared by more than one visitor ----
/** soft contact shadow on the sand */
const sh = (x: number, rx: number, y = 0): TemplateResult => svg`<ellipse cx=${x} cy=${y} rx=${rx} ry=${Math.max(1.6, rx * 0.13)} fill="#4a3415" opacity=".2"/>`;
/** a silver gull on the wing, facing right: it glides, then takes a few beats. `d` staggers the beats, `p` is the rhythm in seconds */
const gull = (x: number, y: number, s = 1, d = 0, p = 3.1): TemplateResult => svg`<g transform="translate(${x} ${y}) scale(${s})"><g class="sea-beat" style="--p:${p}s;animation-delay:${d - 0.09}s"><path d="M4-2Q1-21-13-31Q-11-15-8-1z" fill="#8f9ba8"/></g><path d="M-13-1L-28-3-26 3-12 4z" fill="#fff"/><path d="M-16 1Q-8-8 6-7Q13-10 18-8Q22-6 21-3Q14 6 2 7Q-10 7-16 1z" fill="#fff"/><path d="M-15 2Q-2 9 14 3Q8 7 2 7Q-10 7-15 2z" fill="#d5dee8"/><path d="M20-6.5l8 2.3-8 1.7z" fill="#c8102e"/><circle cx="17" cy="-5.5" r=".9" fill="#2a2a2a"/><g class="sea-beat" style="--p:${p}s;animation-delay:${d}s"><path d="M6-3Q2-23-14-34Q-11-17-9-1z" fill="#b9c3cd"/><path d="M-8.5-25L-14-34-11.4-20z" fill="#1f2328"/><path d="M5-4Q3-14-3-22Q-3-12-4-2z" fill="#d3dae1"/></g></g>`;
/** Carnaby's black cockatoo: slow, deep beats */
const cocky = (x: number, y: number, s: number, d: number): TemplateResult => svg`<g transform="translate(${x} ${y}) scale(${s})"><g class="sea-flap" style="--p:.66s;animation-delay:${d - 0.08}s"><path d="M2-3Q-4-24 14-33Q14-18 16-3z" fill="#191715"/></g><path d="M-12-3L-34-5-34 4-12 4z" fill="#26221f"/><path d="M-31-4.7h9v8.5h-9z" fill="#ece6d4"/><path d="M-16 0Q-8-9 6-8Q14-12 21-10Q26-7 25-2Q18 7 2 8Q-10 8-16 0z" fill="#2e2a26"/><path d="M-14 2Q0 9 18 3Q10 8 2 8Q-10 8-14 2z" fill="#1b1917"/><path d="M12-10Q15-16 21-13z" fill="#26221f"/><ellipse cx="15" cy="-2.5" rx="2.3" ry="1.7" fill="#d9d2bf"/><path d="M24-7Q29-6 27 0Q25-2 23-3z" fill="#55514c"/><circle cx="21" cy="-7.5" r=".8" fill="#0c0b0a"/><g class="sea-flap" style="--p:.66s;animation-delay:${d}s"><path d="M4-4Q-4-28 18-38Q16-20 18-3z" fill="#2e2a26"/><path d="M5-6Q2-20 12-28Q11-16 12-5z" fill="#403b35"/></g></g>`;
/** a black swan in line astern: neck straight out, white flight feathers flashing */
const swan = (x: number, y: number, s: number, d: number): TemplateResult => svg`<g transform="translate(${x} ${y}) scale(${s})"><g class="sea-flap" style="--p:.52s;--f:-.75;animation-delay:${d - 0.07}s"><path d="M-2-3Q-10-22 6-32Q6-18 10-3z" fill="#fff"/><path d="M-2-3Q-7-16 1-22Q3-12 8-3z" fill="#16171a"/></g><path d="M-22 0Q-14-8 0-8Q12-8 16-3Q10 6-4 6Q-16 6-22 0z" fill="#1f2125"/><path d="M-20 1Q-6 8 12 1Q6 6-4 6Q-16 6-20 1z" fill="#0f1012"/><path d="M-20-1l-9 1 8 3z" fill="#1f2125"/><path d="M12-6Q26-8 44-7L45-4Q28-3 14 0z" fill="#1f2125"/><path d="M43-8.5Q49-9 51-6Q49-4 44-3.5z" fill="#1f2125"/><path d="M50-7.5l8 1.7-8 1.5z" fill="#c0392b"/><path d="M54.5-6.8l1.5.4-1.5.5z" fill="#fff"/><g class="sea-flap" style="--p:.52s;--f:-.75;animation-delay:${d}s"><path d="M0-4Q-10-26 8-37Q8-20 13-3z" fill="#fff"/><path d="M0-4Q-7-19 3-26Q5-14 11-3z" fill="#26282d"/></g></g>`;
