/** where the sun sits in the sea theme, by the clock (percent of the width and height): high at noon, sinking behind the page late in the day, gone by ten past seven */
const SUN_Y = [[360, 9], [540, 3], [720, 1.5], [900, 4], [1020, 12], [1080, 26], [1150, 53]];
const SUN_X = [[360, 24], [720, 34], [1080, 52], [1150, 58]];
const cloud = (y: number, w: number, o: number, t: number, d: number): TemplateResult => html`<i class="sea-cl" style="--y:${y}%;--w:${w}vw;--o:${o};--t:${t}s;--d:${-d * t}s"></i>`;
const grass = (cls: string, a: string, b: string): TemplateResult => html`<svg class="sea-grass ${cls}" viewBox="0 0 92 70" fill="none" stroke-linecap="round"><path d="M40 70Q30 40 8 30M44 70Q40 34 26 12M48 70Q50 30 44 4M52 70Q58 36 72 16M56 70Q66 46 88 38" stroke=${a} stroke-width="2.6"/><path d="M42 70Q34 46 18 44M50 70Q54 40 60 22M46 70Q46 44 36 28" stroke=${b} stroke-width="2.2"/><path d="M26 12l-3-7M44 4l-1-8M72 16l4-7" stroke=${b} stroke-width="4"/></svg>`;
const FLAG = html`<svg class="sea-flag" viewBox="0 0 46 96"><path d="M6 96V4" stroke="#f4f1e6" stroke-width="3" stroke-linecap="round"/><path d="M7.2 96V4" stroke="#bfb9a8" stroke-width="1"/><g class="sea-fly"><path d="M8 6h34v22H8z" fill="#f4c81f"/><path d="M8 6h34v11H8z" fill="#d93a2b"/><path d="M20 6h6v22h-6z" fill="#000" opacity=".1"/><path d="M30 6h4v22h-4z" fill="#fff" opacity=".16"/></g></svg>`;
const LIGHTHOUSE = html`<svg class="sea-light" viewBox="0 0 120 120"><defs><linearGradient id="sea-bm" x1="1" x2="0"><stop offset="0" stop-color="#fff6c8" stop-opacity=".7"/><stop offset="1" stop-color="#fff6c8" stop-opacity="0"/></linearGradient></defs><path class="sea-beam" d="M78 23L-520-40v126z" fill="url(#sea-bm)"/><path d="M18 120q10-22 34-24q10-12 30-8q22-2 38 14v18z" fill="#3b4658"/><path d="M52 96q10-12 30-8q-16 2-22 10z" fill="#566277"/><path d="M68 92l4-58h12l4 58z" fill="#f1eee4"/><path d="M80 34h4l4 58h-6z" fill="#c9c6bb"/><path d="M69.5 70h17l1 11h-19zM71 47h14l.8 11H70.2z" fill="#c9443b"/><path d="M66 34h24v-4H66zM72 16h12l3 4H69z" fill="#2b3340"/><rect x="71" y="18" width="14" height="12" fill="#ffe27a"/><circle class="sea-lamp" cx="78" cy="23" r="15" fill="#fff6c8" opacity=".5"/></svg>`;

export const sea: Scene = {
  css: css`
    .sea-w { position: absolute; inset: 0; --sea-c: 255,255,255; }
    .sea-w i, .sea-w svg { position: absolute; display: block; }
    /* clouds: soft blobs, three speeds */
    .sea-cl { left: 0; top: var(--y); width: var(--w); height: calc(var(--w) * .36); opacity: var(--o); animation: sea-drift var(--t) linear infinite; animation-delay: var(--d);
      background: radial-gradient(closest-side, rgba(var(--sea-c),1) 50%, rgba(var(--sea-c),0)) 4% 100% / 46% 60% no-repeat, radial-gradient(closest-side, rgba(var(--sea-c),1) 50%, rgba(var(--sea-c),0)) 30% 0 / 44% 88% no-repeat, radial-gradient(closest-side, rgba(var(--sea-c),1) 50%, rgba(var(--sea-c),0)) 66% 30% / 44% 74% no-repeat, radial-gradient(closest-side, rgba(var(--sea-c),1) 50%, rgba(var(--sea-c),0)) 98% 100% / 40% 52% no-repeat, radial-gradient(closest-side, rgba(var(--sea-c),.9) 40%, rgba(var(--sea-c),0)) 50% 100% / 90% 50% no-repeat; }
    @keyframes sea-drift { from { transform: translateX(-34vw); } to { transform: translateX(104vw); } }
    .sea-far { top: 8.5%; left: 0; width: 64px; opacity: .5; animation: sea-drift 173s linear infinite; animation-delay: -61s; }
    /* sun, its rays and the glitter under it */
    .sea-rays { inset: -30%; background: repeating-conic-gradient(from 4deg at var(--rx) var(--ry), transparent 0 9deg, var(--ray) 13deg 17deg, transparent 21deg 30deg); -webkit-mask-image: radial-gradient(circle at var(--rx) var(--ry), #000 4vmax, rgba(0,0,0,.45) 20vmax, transparent 46vmax); mask-image: radial-gradient(circle at var(--rx) var(--ry), #000 4vmax, rgba(0,0,0,.45) 20vmax, transparent 46vmax); transform-origin: var(--rx) var(--ry); animation: sea-turn 73s ease-in-out infinite alternate; }
    @keyframes sea-turn { from { transform: rotate(-9deg); } to { transform: rotate(9deg); } }
    .sea-sun { left: var(--sx); top: var(--sy); width: var(--sz); height: var(--sz); margin: calc(var(--sz) / -2) 0 0 calc(var(--sz) / -2); border-radius: 50%; animation: sea-breathe 13s ease-in-out infinite alternate; }
    @keyframes sea-breathe { from { transform: scale(.94); opacity: .82; } to { transform: scale(1.08); opacity: 1; } }
    .sea-glit { width: 16vw; margin-left: -8vw; left: var(--sx); background: repeating-linear-gradient(0deg, transparent 0 5px, rgba(var(--sea-g),.75) 5px 7px, transparent 7px 11px); -webkit-mask-image: radial-gradient(ellipse 50% 62% at 50% 30%, #000 20%, transparent); mask-image: radial-gradient(ellipse 50% 62% at 50% 30%, #000 20%, transparent); animation: sea-glit 3.7s ease-in-out infinite alternate; }
    @keyframes sea-glit { from { transform: translateY(-3px) scaleX(.86); opacity: .45; } to { transform: translateY(3px) scaleX(1.06); opacity: 1; } }
    /* water: wide soft bands sliding along the horizon, and the foam line breathing on the shore */
    .sea-band { left: 0; width: 200vw; background: repeating-linear-gradient(90deg, transparent 0 3vw, rgba(255,255,255,var(--bo)) 8vw 11vw, transparent 16vw 20vw); -webkit-mask-image: linear-gradient(transparent, #000 35%, #000 65%, transparent); mask-image: linear-gradient(transparent, #000 35%, #000 65%, transparent); animation: sea-slide 67s linear infinite; }
    .sea-band.b { animation-duration: 109s; animation-direction: reverse; }
    @keyframes sea-slide { from { transform: skewX(-28deg) translateX(0); } to { transform: skewX(-28deg) translateX(-100vw); } }
    .sea-foam { left: -10vw; width: 130vw; height: 22px; background: radial-gradient(closest-side, rgba(255,255,255,.85) 60%, transparent) 0 0 / 9vw 22px repeat-x; animation: sea-foam 17s ease-in-out infinite alternate; }
    @keyframes sea-foam { from { transform: translate(-8vw, -9px); opacity: .5; } to { transform: translate(0, 9px); opacity: 1; } }
    /* dune grass (a far tuft and a near one each side) and the patrol flag in the breeze */
    .sea-grass { bottom: -4px; width: 92px; transform-origin: 50% 100%; animation: sea-sway 5.3s ease-in-out infinite alternate; }
    .sea-grass.r { right: -14px; animation-duration: 7.1s; } .sea-grass.l { left: -14px; }
    .sea-grass.fl { left: 34px; width: 54px; opacity: .8; animation-duration: 6.1s; animation-delay: -2s; } .sea-grass.fr { right: 70px; width: 50px; opacity: .8; animation-duration: 8.3s; animation-delay: -3s; }
    @keyframes sea-sway { from { transform: skewX(-8deg); } to { transform: skewX(6deg); } }
    .sea-flag { right: 46px; bottom: 0; width: 46px; overflow: visible; }
    .sea-fly { transform-origin: 0 50%; transform-box: fill-box; animation: sea-fly 1.9s ease-in-out infinite alternate; }
    @keyframes sea-fly { from { transform: scaleX(1) skewY(-5deg); } to { transform: scaleX(.86) skewY(7deg); } }
    /* night: stars, moon, and the lighthouse on the point */
    .sea-stars { left: 0; top: 0; width: 2px; height: 2px; border-radius: 50%; animation: sea-twk 3.1s ease-in-out infinite alternate; }
    @keyframes sea-twk { from { opacity: .25; } to { opacity: 1; } }
    .sea-star1 { width: 13px; animation: sea-twk 2.3s ease-in-out infinite alternate; }
    .sea-light { right: 0; bottom: 0; width: 120px; overflow: visible; }
    .sea-beam { transform-origin: 78px 23px; animation: sea-beam 7s ease-in-out infinite alternate; }
    @keyframes sea-beam { from { transform: scaleX(1); } to { transform: scaleX(-1); } }
    .sea-lamp { animation: sea-lamp 7s ease-in-out infinite alternate; }
    @keyframes sea-lamp { 0%, 100% { opacity: .35; } 50% { opacity: 1; } }

    /* ---- parts every visitor may use ---- */
    .guest[data-flip][class*='sea-'] { --sd: -1; }
    .sea-e { left: 0; } .guest[data-flip].sea-e { left: auto; right: 0; }
    /* a wing seen from the side: scaleY about the shoulder. "beat" glides, then takes three beats; "flap" beats all the time */
    .sea-beat, .sea-flap { transform-box: fill-box; transform-origin: var(--o, 50% 100%); }
    .sea-beat { animation: sea-beat var(--p, 3.1s) ease-in-out infinite; }
    @keyframes sea-beat { 0%, 50%, 100% { transform: scaleY(var(--g, .42)); } 58%, 74%, 90% { transform: scaleY(1); } 66%, 82% { transform: scaleY(var(--f, -.7)); } }
    .sea-flap { animation: sea-flap var(--p, .42s) ease-in-out infinite alternate; }
    @keyframes sea-flap { from { transform: scaleY(1); } to { transform: scaleY(var(--f, -.7)); } }
    .sea-wig { transform-box: fill-box; transform-origin: var(--o, center); animation: sea-wig var(--p, .4s) ease-in-out infinite alternate; }
    @keyframes sea-wig { from { transform: rotate(var(--a, -12deg)); } to { transform: rotate(var(--b, 12deg)); } }
    .sea-bob { animation: sea-bob var(--p, .5s) ease-in-out infinite alternate; }
    @keyframes sea-bob { from { transform: translateY(0); } to { transform: translateY(var(--h, -4px)); } }
    .sea-soar > svg { animation: sea-soar 5.3s ease-in-out infinite alternate; }
    @keyframes sea-soar { from { translate: 0 -6px; rotate: -2deg; } to { translate: 0 7px; rotate: 2.5deg; } }
    .sea-mov { --m: 1; --s: 0; } .sea-stl { --m: 0; --s: 1; }
    /* sky */
    .sea-lag { animation: sea-lag var(--t) ease-in-out both; }
    @keyframes sea-lag { 0%, 14%, 78%, 100% { transform: translateX(0); } 36%, 52% { transform: translateX(var(--lag, -64px)); } }
    .sea-gulp { transform-box: fill-box; transform-origin: 8% 50%; animation: sea-gulp var(--t) ease-in-out both; }
    @keyframes sea-gulp { 0%, 30%, 33%, 47%, 100% { transform: rotate(0); } 31.5% { transform: rotate(5deg); } 37%, 42% { transform: rotate(-40deg); } }
    .sea-fish { transform-box: fill-box; transform-origin: 0 50%; animation: sea-fish var(--t) linear both; }
    @keyframes sea-fish { 0%, 6%, 12%, 18%, 24%, 30%, 36% { transform: rotate(-16deg); opacity: 1; } 3%, 9%, 15%, 21%, 27%, 33% { transform: rotate(18deg); opacity: 1; } 40%, 100% { transform: rotate(0); opacity: 0; } }
    .sea-tern { --q: 34vw; animation: sea-tern var(--t) both; } .guest[data-flip].sea-tern { --q: 60vw; }
    @keyframes sea-tern { 0% { transform: translate(calc(var(--sd, 1) * -90px), 2vh); animation-timing-function: ease-out; } 22% { transform: translate(calc(var(--sd, 1) * var(--q)), 0); } 30% { transform: translate(calc(var(--sd, 1) * (var(--q) + 1vw)), -1.5vh); } 38% { transform: translate(calc(var(--sd, 1) * var(--q)), -.5vh); animation-timing-function: ease-in; } 43%, 50% { transform: translate(calc(var(--sd, 1) * (var(--q) + 3vw)), 36vh); animation-timing-function: ease-out; } 58% { transform: translate(calc(var(--sd, 1) * (var(--q) + 8vw)), 1vh); animation-timing-function: ease-in-out; } 100% { transform: translate(calc(var(--sd, 1) * (100vw + 90px)), -2vh); } }
    .sea-tern svg { animation: sea-tilt var(--t) ease-in-out both; }
    @keyframes sea-tilt { 0%, 20% { rotate: 0deg; } 24%, 37% { rotate: calc(var(--sd, 1) * 14deg); } 41%, 44% { rotate: calc(var(--sd, 1) * 82deg); } 51%, 55% { rotate: calc(var(--sd, 1) * -38deg); } 62%, 100% { rotate: 0deg; } }
    .sea-catch { animation: sea-catch var(--t) step-end both; }
    @keyframes sea-catch { 0% { opacity: 0; } 47%, 100% { opacity: 1; } }
    .sea-kite { --p1: 27vw; --p2: 41vw; animation: sea-kite var(--t) ease-in-out both; } .guest[data-flip].sea-kite { --p1: 59vw; --p2: 73vw; }
    @keyframes sea-kite { 0% { transform: translate(calc(var(--sd, 1) * -120px), 12vh); } 26% { transform: translate(calc(var(--sd, 1) * var(--p1)), 1vh); } 60% { transform: translate(calc(var(--sd, 1) * var(--p2)), 2vh); } 100% { transform: translate(calc(var(--sd, 1) * (100vw + 120px)), -2vh); } }
    .sea-kite svg { transform-origin: 50% 104%; animation: sea-loop var(--t) ease-in-out both; }
    @keyframes sea-loop { 0% { rotate: calc(var(--sd, 1) * 14deg); } 12% { rotate: calc(var(--sd, 1) * -8deg); } 26% { rotate: calc(var(--sd, 1) * 10deg); } 32% { rotate: calc(var(--sd, 1) * -12deg); } 46% { rotate: calc(var(--sd, 1) * 364deg); } 52% { rotate: calc(var(--sd, 1) * 350deg); } 64% { rotate: calc(var(--sd, 1) * 724deg); } 80% { rotate: calc(var(--sd, 1) * 708deg); } 100% { rotate: calc(var(--sd, 1) * 728deg); } }
    .sea-rear { transform-box: fill-box; transform-origin: 0 90%; animation: sea-rear var(--t) ease-in-out both; }
    @keyframes sea-rear { 0%, 28%, 44%, 100% { transform: rotate(0); } 33% { transform: rotate(-16deg); } 36%, 41% { transform: rotate(5deg); } }
    .sea-fire { transform-box: fill-box; transform-origin: 0 50%; animation: sea-fire var(--t) ease-out both; }
    @keyframes sea-fire { 0%, 35%, 43%, 100% { transform: scale(0); opacity: 0; } 37% { transform: scale(1); opacity: 1; } 41% { transform: scale(1.15, .8); opacity: .8; } }
    .sea-lift { animation: sea-lift 9.7s ease-in-out infinite; }
    @keyframes sea-lift { 0%, 100% { transform: translateY(16px) rotate(-1.5deg); } 45% { transform: translateY(0) rotate(1.5deg); } }
    .sea-flame { animation: sea-flame 9.7s linear infinite; }
    @keyframes sea-flame { 0%, 8%, 31%, 100% { opacity: 0; } 11%, 28% { opacity: 1; } }
    .sea-hi > svg { animation: sea-hi var(--t) ease-in-out both; }
    @keyframes sea-hi { 0%, 28%, 48%, 100% { translate: 0 0; } 34% { translate: 0 -11px; } 41% { translate: 0 9px; } }
    .sea-wag { transform-box: fill-box; transform-origin: 50% 50%; animation: sea-wag var(--t) ease-in-out both; }
    @keyframes sea-wag { 0%, 26%, 50%, 100% { rotate: 0deg; } 30%, 38%, 46% { rotate: -8deg; } 34%, 42% { rotate: 8deg; } }
    .sea-prop { transform-box: fill-box; transform-origin: center; animation: sea-prop .5s ease-in-out infinite alternate; }
    @keyframes sea-prop { from { transform: scaleY(1); } to { transform: scaleY(.6); } }
    .sea-puff { transform-box: fill-box; transform-origin: 50% 100%; animation: sea-puff 6.3s ease-out infinite; }
    @keyframes sea-puff { 0%, 55% { transform: translateY(16px) scale(.2); opacity: 0; } 65% { opacity: 1; } 85% { transform: translateY(0) scale(1); opacity: 1; } 100% { transform: translateY(-8px) scale(1.15); opacity: 0; } }
    .sea-neck { transform-box: fill-box; transform-origin: 0 100%; animation: sea-neck var(--t) ease-in-out both; }
    @keyframes sea-neck { 0%, 26%, 56%, 100% { transform: rotate(0); } 32%, 36%, 44%, 48% { transform: rotate(16deg); } 34%, 40%, 46% { transform: rotate(12deg); } }
    .sea-nib { animation: sea-nib var(--t) linear both; }
    @keyframes sea-nib { 0%, 33% { opacity: 1; } 47%, 100% { opacity: 0; } }
    .sea-blink { transform-box: fill-box; transform-origin: center; animation: sea-blink 4.3s linear infinite; }
    @keyframes sea-blink { 0%, 90%, 100% { transform: scaleY(1); } 94% { transform: scaleY(.1); } }
    /* the sand corners */
    .sea-st { top: auto; bottom: 0; left: 0; } .guest[data-flip].sea-st { left: auto; right: 0; }
    .sea-st > svg { display: block; width: max(15vw, 170px); overflow: visible; }
    .sea-crab { animation: sea-crab var(--t) ease-in-out both; }
    @keyframes sea-crab { 0% { transform: translate(-70px, 120px); } 24%, 64% { transform: translate(88px, 120px); } 88%, 100% { transform: translate(-70px, 120px); } }
    .sea-hello { transform-box: fill-box; transform-origin: 0 100%; animation: sea-hello var(--t) ease-in-out both; }
    @keyframes sea-hello { 0%, 28%, 64%, 100% { transform: rotate(40deg); } 33%, 43%, 53% { transform: rotate(-14deg); } 38%, 48%, 58% { transform: rotate(12deg); } }
    .sea-ghost { animation: sea-ghost var(--t) both; }
    @keyframes sea-ghost { 0% { transform: translate(-40px, 121px); animation-timing-function: ease-out; } 6%, 28% { transform: translate(40px, 121px); animation-timing-function: ease-out; } 32%, 58% { transform: translate(98px, 121px); animation-timing-function: ease-out; } 61%, 80% { transform: translate(70px, 121px); animation-timing-function: ease-in; } 87%, 100% { transform: translate(-50px, 121px); } }
    .sea-box { animation: sea-box var(--t) ease-out both; }
    @keyframes sea-box { 0% { transform: translateY(-14px); opacity: 0; } 4%, 90% { transform: translateY(0); opacity: 1; } 100% { transform: translateY(0); opacity: 0; } }
    .sea-thief { animation: sea-thief var(--t) ease-in-out both; }
    @keyframes sea-thief { 0% { transform: translate(-50px, 36px); } 20%, 36% { transform: translate(34px, 122px); } 39% { transform: translate(42px, 116px); } 42% { transform: translate(50px, 122px); } 45% { transform: translate(58px, 116px); } 48% { transform: translate(66px, 122px); } 51% { transform: translate(70px, 117px); } 54%, 66% { transform: translate(74px, 122px); animation-timing-function: ease-in; } 100% { transform: translate(330px, 30px); } }
    .sea-upp { --u: 1; --v: 0; } .sea-down { --u: 0; --v: 1; }
    .sea-upp, .sea-down { animation: sea-upp var(--t) step-end both; }
    @keyframes sea-upp { 0% { opacity: var(--u); } 20% { opacity: var(--v); } 66%, 100% { opacity: var(--u); } }
    .sea-shifty { transform-box: fill-box; transform-origin: 20% 80%; animation: sea-shifty var(--t) ease-in-out both; }
    @keyframes sea-shifty { 0%, 22%, 36%, 100% { transform: rotate(0); } 25%, 28% { transform: rotate(-44deg); } 31%, 34% { transform: rotate(10deg); } }
    .sea-peck { transform-box: fill-box; transform-origin: 40% 100%; animation: sea-peck var(--t) ease-in-out both; }
    @keyframes sea-peck { 0%, 55%, 64%, 100% { transform: rotate(0); } 58%, 61% { transform: rotate(32deg); } }
    .sea-loot { animation: sea-loot var(--t) step-end both; }
    @keyframes sea-loot { 0% { opacity: 0; } 60%, 100% { opacity: 1; } }
    .sea-ball { animation: sea-ball var(--t) linear both; }
    @keyframes sea-ball { 0% { transform: translate(-12px, 40px); animation-timing-function: ease-in; } 4% { transform: translate(22px, 116px); animation-timing-function: ease-out; } 7% { transform: translate(44px, 74px); animation-timing-function: ease-in; } 10% { transform: translate(66px, 116px); animation-timing-function: ease-out; } 12% { transform: translate(82px, 97px); animation-timing-function: ease-in; } 14% { transform: translate(98px, 116px); animation-timing-function: ease-out; } 22%, 44% { transform: translate(127px, 116px) rotate(220deg); opacity: 1; } 44.1%, 100% { transform: translate(127px, 116px); opacity: 0; } }
    .sea-dog { animation: sea-dog var(--t) both; }
    @keyframes sea-dog { 0%, 14% { transform: translate(-100px, 121px); animation-timing-function: ease-out; } 38%, 58% { transform: translate(72px, 121px); animation-timing-function: ease-in; } 86%, 100% { transform: translate(-110px, 121px); } }
    .sea-about { transform-box: fill-box; transform-origin: center; animation: sea-about var(--t) step-end both; }
    @keyframes sea-about { 0% { transform: scaleX(1); } 52%, 100% { transform: scaleX(-1); } }
    .sea-dog .sea-mov, .sea-dog .sea-stl { animation: sea-dogm var(--t) step-end both; }
    @keyframes sea-dogm { 0% { opacity: var(--m); } 38% { opacity: var(--s); } 58%, 100% { opacity: var(--m); } }
    .sea-nose { transform-box: fill-box; transform-origin: 0 100%; animation: sea-nose var(--t) ease-in-out both; }
    @keyframes sea-nose { 0%, 39%, 49%, 100% { transform: rotate(0); } 43%, 45% { transform: rotate(24deg); } }
    .sea-got { animation: sea-got var(--t) step-end both; }
    @keyframes sea-got { 0% { opacity: 0; } 44%, 100% { opacity: 1; } }
    .sea-scoot { animation: sea-scoot var(--t) both; }
    @keyframes sea-scoot { 0% { transform: translate(-70px, 121px); animation-timing-function: ease-out; } 24%, 62% { transform: translate(92px, 121px); animation-timing-function: ease-in; } 100% { transform: translate(430px, 121px); } }
    .sea-hop { transform-box: fill-box; transform-origin: 20% 100%; animation: sea-hop var(--t) ease-in-out both; }
    @keyframes sea-hop { 0%, 18% { transform: rotate(-3deg); } 24% { transform: rotate(5deg); } 30%, 60% { transform: rotate(0); } 68%, 100% { transform: rotate(-5deg); } }
    .sea-kick { transform-box: fill-box; transform-origin: 100% 0; animation: sea-kick var(--t) ease-in-out both; }
    @keyframes sea-kick { 0%, 9%, 18%, 60%, 69%, 78%, 100% { transform: rotate(-30deg); } 4.5%, 13.5%, 64.5%, 73.5% { transform: rotate(34deg); } }
    .sea-nod { transform-box: fill-box; transform-origin: 20% 100%; animation: sea-nod var(--t) ease-in-out both; }
    @keyframes sea-nod { 0%, 30%, 58%, 100% { transform: rotate(0); } 36%, 44% { transform: rotate(-14deg); } 40% { transform: rotate(-9deg); } 50% { transform: rotate(6deg); } }
    .sea-ear { transform-box: fill-box; transform-origin: 50% 100%; animation: sea-ear 2.9s ease-in-out infinite; }
    @keyframes sea-ear { 0%, 80%, 100% { transform: rotate(0); } 86%, 94% { transform: rotate(-18deg); } 90% { transform: rotate(8deg); } }
    .sea-herm { animation: sea-herm var(--t) ease-in-out both; }
    @keyframes sea-herm { 0% { transform: translate(-70px, 121px); } 36%, 64% { transform: translate(72px, 121px); } 100% { transform: translate(350px, 121px); } }
    .sea-shy { transform-box: fill-box; transform-origin: 0 60%; animation: sea-shy var(--t) both; }
    @keyframes sea-shy { 0%, 39% { transform: scale(1); animation-timing-function: ease-in; } 41%, 52% { transform: scale(0); animation-timing-function: ease-out; } 55%, 58% { transform: scale(.45); animation-timing-function: ease-out; } 62%, 100% { transform: scale(1); } }
    .sea-truck { animation: sea-truck var(--t) ease-in-out both; }
    @keyframes sea-truck { 0% { transform: translate(-100px, 115px); } 22%, 62% { transform: translate(104px, 115px); } 100% { transform: translate(440px, 115px); } }
    .sea-rock { transform-box: fill-box; transform-origin: 50% 100%; animation: sea-rock var(--t) ease-in-out both; }
    @keyframes sea-rock { 0%, 20%, 27%, 60%, 68%, 100% { transform: rotate(0); } 23% { transform: rotate(2.5deg); } 64% { transform: rotate(-2.5deg); } }
    .sea-tip { transform-box: fill-box; transform-origin: 0 100%; animation: sea-tip var(--t) ease-in-out both; }
    @keyframes sea-tip { 0%, 28%, 58%, 100% { transform: rotate(0); } 38%, 48% { transform: rotate(-36deg); } 50% { transform: rotate(-32deg); } 52% { transform: rotate(-36deg); } }
    .sea-load { animation: sea-load var(--t) linear both; }
    @keyframes sea-load { 0%, 35% { opacity: 1; } 42%, 100% { opacity: 0; } }
    .sea-pile { transform-box: fill-box; transform-origin: 50% 100%; animation: sea-pile var(--t) ease-out both; }
    @keyframes sea-pile { 0%, 36% { transform: scale(0); opacity: 1; } 46%, 92% { transform: scale(1); opacity: 1; } 100% { transform: scale(1); opacity: 0; } }
    .sea-bobt { animation: sea-bobt var(--t) linear both; }
    @keyframes sea-bobt { 0% { transform: translate(-80px, 121px); } 100% { transform: translate(380px, 121px); } }
    .sea-lick { transform-box: fill-box; transform-origin: 0 50%; animation: sea-lick var(--t) ease-in-out both; }
    @keyframes sea-lick { 0%, 14%, 17.5%, 21%, 30%, 33.5%, 37%, 100% { transform: scaleX(0); } 15.5%, 19%, 31.5%, 35% { transform: scaleX(1); } }
    .sea-plov { animation: sea-plov var(--t) both; }
    @keyframes sea-plov { 0% { transform: translateX(calc(var(--sd, 1) * -50px)); animation-timing-function: ease-out; } 11%, 26% { transform: translateX(calc(var(--sd, 1) * 5vw)); animation-timing-function: ease-in-out; } 30%, 36% { transform: translateX(calc(var(--sd, 1) * 11vw)); animation-timing-function: ease-in-out; } 60%, 74% { transform: translateX(calc(var(--sd, 1) * 91vw)); animation-timing-function: ease-in; } 100% { transform: translateX(calc(var(--sd, 1) * (100vw + 50px))); } }
    .sea-plov .sea-mov, .sea-plov .sea-stl { animation: sea-plovm var(--t) step-end both; }
    @keyframes sea-plovm { 0%, 26%, 36%, 74% { opacity: var(--m); } 11%, 30%, 60% { opacity: var(--s); } }
    .sea-dip { transform-box: fill-box; transform-origin: 40% 100%; animation: sea-dip var(--t) ease-in-out both; }
    @keyframes sea-dip { 0%, 13%, 17%, 21%, 62%, 66%, 70%, 100% { transform: rotate(0); } 15%, 19%, 64%, 68% { transform: rotate(38deg); } }
    .sea-roll > svg { animation: sea-spin 1.7s linear infinite, sea-bnc 1.1s ease-out infinite alternate; --bh: -13px; }
    /* in front */
    .sea-pod { white-space: nowrap; }
    .sea-pod > svg { animation: sea-leap 3.4s linear infinite both; }
    @keyframes sea-leap { 0% { translate: 0 24px; rotate: calc(var(--sd, 1) * -52deg); opacity: 0; animation-timing-function: ease-out; } 8% { opacity: 1; } 28% { translate: 0 -30px; rotate: 0deg; opacity: 1; animation-timing-function: ease-in; } 48% { opacity: 1; } 56%, 100% { translate: 0 24px; rotate: calc(var(--sd, 1) * 52deg); opacity: 0; } }
    .sea-bb > svg { animation: sea-bnc .64s ease-out infinite alternate; }
    @keyframes sea-bnc { from { translate: 0 0; } to { translate: 0 var(--bh, -54px); } }
    .sea-spin { animation: sea-spin 2.3s linear infinite; }
    @keyframes sea-spin { to { rotate: calc(var(--sd, 1) * 360deg); } }
  `,
  always: (c) => {
    const night = c.tod === 'night', sunset = c.theme === 'sunset', warm = golden(c), winter = c.month >= 6 && c.month <= 8;
    // the sun: fixed low in the sunset picture; by the clock in the sea picture
    const sx = night ? 34 + ((c.mins + 180) % 1440) / 60 : sunset ? 72 : lerp(SUN_X, c.mins), sy = night ? 5 : sunset ? 49 : lerp(SUN_Y, c.mins);
    const up = !night && (sunset || c.mins < 1150), low = sy > 14, sea0 = sunset ? 58 : 52;
    const tint = night ? '176,190,216' : sunset ? '255,226,200' : warm ? '255,236,224' : '255,255,255';
    const g1 = night ? '#6d7a6a' : warm ? '#a8935a' : '#a9a25e', g2 = night ? '#8a957f' : warm ? '#d2b878' : '#c9bf7c';
    return html`<div class="sea-w" style="--sea-c:${tint};--sea-g:${night ? '214,226,255' : warm ? '255,224,170' : '255,255,255'};--sx:${sx.toFixed(1)}%;--sy:${sy.toFixed(1)}%;--rx:${((30 + sx) / 1.6).toFixed(2)}%;--ry:${((30 + sy) / 1.6).toFixed(2)}%;--ray:${low ? 'rgba(255,214,150,.2)' : 'rgba(255,255,255,.17)'};--bo:${night ? 0.16 : 0.34}">
      ${up ? html`<i class="sea-rays"></i><i class="sea-sun" style="--sz:${low ? '38vmin' : '150px'};background:${low ? 'radial-gradient(circle, #fff3c4 0 13%, rgba(255,214,130,.8) 16%, rgba(255,170,90,.3) 38%, transparent 68%)' : 'radial-gradient(circle, #fffbe2 0 21%, rgba(255,243,180,.8) 24%, rgba(255,240,170,.3) 42%, transparent 70%)'}"></i>` : nothing}
      ${night ? html`<i class="sea-stars" style="box-shadow:${stars(7, 5)}"></i><i class="sea-stars" style="box-shadow:${stars(6, 11)};animation-duration:4.3s"></i><i class="sea-stars" style="box-shadow:${stars(6, 23)};animation-duration:5.9s"></i>
        <svg viewBox="0 0 60 60" width="58" style="left:${sx.toFixed(1)}%;top:18px"><circle cx="30" cy="30" r="29" fill="#fff" opacity=".12"/><circle cx="30" cy="30" r="21" fill="#f6f1dc"/><path d="M30 9a21 21 0 0 1 0 42a26 21 0 0 0 0-42z" fill="#e4dcc0"/><circle cx="23" cy="24" r="4.5" fill="#ddd6bb"/><circle cx="36" cy="35" r="6" fill="#d3cbae"/><circle cx="27" cy="40" r="2.5" fill="#ddd6bb"/></svg>` : nothing}
      ${!night && warm && c.mins >= 1140 ? html`<svg class="sea-star1" viewBox="-11 -11 22 22" style="left:41%;top:4%"><path d="M0-10Q1-1 10 0Q1 1 0 10Q-1 1-10 0Q-1-1 0-10z" fill="#fff"/></svg>` : nothing}
      ${cloud(7, 13, 0.7, 241, 0.42)}${cloud(1.5, 19, 0.88, 163, 0.1)}${cloud(-4, 27, 0.95, 107, 0.68)}${cloud(4, 16, 0.8, 197, 0.83)}${winter ? cloud(-2, 24, 0.9, 89, 0.3) : nothing}
      ${night ? nothing : html`<svg class="sea-far" viewBox="0 0 64 22" fill="none" stroke="#fff" stroke-width="1.4" stroke-linecap="round"><path d="M2 8q4-4 7 0q3-4 7 0M24 15q3-3 6 0q3-3 6 0M40 5q3-3 6 0q3-3 6 0M50 17q2-2 5 0q3-2 5 0"/></svg>`}
      <i class="sea-band" style="top:${sea0}%;height:15%"></i><i class="sea-band b" style="top:${sea0 + 4}%;height:14%"></i>
      <i class="sea-foam" style="top:${sea0 + 18}%"></i>
      ${(up && sx > 30) || night ? html`<i class="sea-glit" style="top:${sea0 + 1}%;height:15%"></i>` : nothing}
      ${grass('fl', g1, g1)}${grass('fr', g1, g1)}${grass('l', g1, g2)}${grass('r', g1, g2)}
      ${night ? LIGHTHOUSE : c.month >= 10 || c.month <= 3 ? FLAG : nothing}
    </div>`;
  },
  cast: CAST,
};

